<template>
  <section class="account-content orders-view"><div class="catalog-heading"><div><p class="eyebrow">交易记录</p><h1>我的订单</h1></div><button class="icon-button" title="刷新订单" aria-label="刷新订单" @click="load">↻</button></div>
    <div class="order-tabs" role="tablist"><button v-for="tab in tabs" :key="tab.value" :class="{ active: status === tab.value }" @click="selectStatus(tab.value)">{{ tab.label }}</button></div>
    <PageStatus :loading="loading" :error="error" :empty="!page?.items.length" empty-text="这里还没有订单" @retry="load" />
    <div v-if="page && !loading && !error" class="order-list"><article v-for="order in page.items" :key="order.id" class="order-card"><header><span>{{ order.orderNo }}</span><time>{{ date(order.createdAt) }}</time><b>{{ statusText(order.status) }}</b></header><div class="order-card-main"><span>{{ order.itemCount }} 件商品</span><strong>¥{{ price(order.totalAmount) }}</strong><button class="text-action" @click="openOrder(order.id)">查看详情</button></div></article></div>
    <PagePagination v-if="page" :total="page.total" :page="page.page" :busy="loading" @change="changePage" />
    <section class="buyer-after-sales"><div class="catalog-heading"><div><p class="eyebrow">退款与退货</p><h2>售后申请</h2></div><button class="icon-button" title="刷新售后" aria-label="刷新售后" @click="loadAfterSales">↻</button></div><PageStatus :loading="afterSalesLoading" :error="afterSalesError" :empty="!afterSales?.items.length" empty-text="暂无售后申请" @retry="loadAfterSales"/><article v-for="item in afterSales?.items" :key="item.id" class="order-card"><header><span>{{ item.requestNo }} · {{ item.type === 'REFUND' ? '退款' : '退货' }}</span><b>{{ afterSaleStatus(item.status) }}</b><time>{{ date(item.createdAt) }}</time></header><p>{{ item.orderNo }} · {{ item.reason }}</p><p v-if="item.reviewReason" class="muted">处理说明：{{ item.reviewReason }}</p><button v-if="item.status === 'WAITING_RETURN'" class="text-action" @click="returnTarget = item.id">登记退货物流</button><form v-if="returnTarget === item.id" class="inline-form" @submit.prevent="sendReturnShipment(item.id)"><label class="form-field">承运商<input v-model="returnCarrier" required maxlength="80"></label><label class="form-field">运单号<input v-model="returnTracking" required maxlength="100"></label><div class="order-actions"><button class="primary-button" :disabled="busy">提交物流</button><button type="button" class="secondary-button" @click="returnTarget = null">取消</button></div></form></article></section>
    <div v-if="selectedOrder" class="order-detail-panel"><div class="catalog-heading"><div><p class="eyebrow">订单详情</p><h2>{{ selectedOrder.orderNo }}</h2></div><button class="icon-button" title="关闭详情" aria-label="关闭详情" @click="selectedOrder = null">×</button></div><p class="order-status-line"><strong>{{ statusText(selectedOrder.status) }}</strong><span>创建于 {{ date(selectedOrder.createdAt) }}</span></p>
      <div class="checkout-lines"><article v-for="item in selectedOrder.items" :key="item.id" class="checkout-line"><img v-if="item.imageUrl" :src="imageUrl(item.imageUrl)" :alt="item.productName"><div><strong>{{ item.productName }}</strong><small>{{ item.specification }} · {{ item.quantity }} 件</small><button v-if="selectedOrder.status === 'COMPLETED' && !item.reviewed" class="text-action" @click="reviewTarget = item.id">评价商品</button><small v-else-if="item.reviewed" class="muted">已评价</small></div><strong>¥{{ price(item.lineAmount) }}</strong></article></div>
      <div class="order-address"><strong>收货信息</strong><p>{{ selectedOrder.recipientName }} · {{ selectedOrder.phone }}</p><p>{{ selectedOrder.province }}{{ selectedOrder.city }}{{ selectedOrder.district }}{{ selectedOrder.detailAddress }}</p></div>
      <div v-if="selectedOrder.carrier" class="order-tracking"><strong>模拟物流 · {{ selectedOrder.carrier }}</strong><p>运单号：{{ selectedOrder.trackingNumber }}</p><ol><li v-for="(event, index) in selectedOrder.trackingEvents" :key="index"><time>{{ date(event.occurredAt) }}</time><span>{{ event.description }}</span></li></ol></div>
      <ol class="order-timeline"><li v-for="(event, index) in selectedOrder.statusEvents" :key="index"><time>{{ date(event.createdAt) }}</time><span>{{ event.note }}</span></li></ol>
      <div class="order-actions"><button v-if="selectedOrder.status === 'PENDING_PAYMENT'" class="primary-button" :disabled="busy" @click="paymentOpen = true">去支付</button><button v-if="selectedOrder.status === 'PENDING_PAYMENT'" class="secondary-button" :disabled="busy" @click="cancel">取消订单</button><button v-if="selectedOrder.status === 'PENDING_SHIPMENT' || selectedOrder.status === 'COMPLETED'" class="secondary-button" :disabled="busy" @click="openAfterSale">申请{{ selectedOrder.status === 'PENDING_SHIPMENT' ? '退款' : '退货' }}</button><button v-if="selectedOrder.status === 'PENDING_RECEIPT'" class="primary-button" :disabled="busy" @click="confirm">确认收货</button></div>
      <p v-if="notice" class="form-message-success" role="status">{{ notice }}</p><p v-if="actionError" class="form-message-error" role="alert">{{ actionError }}</p>
    </div>
    <div v-if="paymentOpen && selectedOrder" class="inline-form"><h3>模拟支付</h3><label class="form-field">支付方式<select v-model="paymentChannel"><option value="ALIPAY">支付宝（模拟）</option><option value="WECHAT">微信支付（模拟）</option></select></label><label class="form-field">模拟结果<select v-model="paymentResult"><option value="SUCCESS">支付成功</option><option value="FAILED">支付失败</option><option value="CANCELLED">取消支付</option></select></label><div class="order-actions"><button class="primary-button" :disabled="busy" @click="pay">确认模拟结果</button><button class="secondary-button" @click="paymentOpen = false">返回</button></div></div>
    <form v-if="afterSaleOpen && selectedOrder" class="inline-form" @submit.prevent="submitAfterSaleForm"><h3>申请{{ selectedOrder.status === 'PENDING_SHIPMENT' ? '退款' : '退货退款' }}</h3><label class="form-field">申请原因<input v-model="afterSaleReason" required maxlength="100" placeholder="请简要说明原因"></label><label class="form-field">补充说明<textarea v-model="afterSaleDescription" maxlength="1000" rows="3"></textarea></label><label v-for="item in selectedOrder.items" :key="item.id" class="checkout-address"><span>{{ item.productName }} · 可申请 {{ Math.max(0, item.quantity - item.refundedQuantity) }} 件</span><input v-model.number="afterSaleQuantities[item.id]" type="number" min="0" :max="item.quantity - item.refundedQuantity"></label><div class="order-actions"><button class="primary-button" :disabled="busy">提交申请</button><button type="button" class="secondary-button" @click="afterSaleOpen = false">返回</button></div></form>
    <form v-if="reviewTarget" class="inline-form" @submit.prevent="sendReview"><h3>评价商品</h3><label class="form-field">评分<select v-model.number="rating"><option :value="5">5 星 · 非常满意</option><option :value="4">4 星 · 满意</option><option :value="3">3 星 · 一般</option><option :value="2">2 星 · 不满意</option><option :value="1">1 星 · 很不满意</option></select></label><label class="form-field">评价内容<textarea v-model="reviewContent" maxlength="2000" rows="4" placeholder="分享商品体验（选填）"></textarea></label><div class="order-actions"><button class="primary-button" :disabled="busy">提交评价</button><button type="button" class="secondary-button" @click="reviewTarget = null">返回</button></div></form>
  </section>
</template>

<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import PageStatus from '../components/PageStatus.vue'
import PagePagination from '../components/PagePagination.vue'
import { errorMessage, imageUrl, price } from '../api/catalog'
import { cancelOrder, confirmReceipt, getOrder, listBuyerAfterSales, listOrders, payOrder, returnShipment, submitAfterSale, submitReview, type AfterSale, type OrderDetail, type OrderFilter, type Page, type OrderSummary } from '../api/orders'

const route = useRoute(), router = useRouter()
const tabs: { label: string; value: OrderFilter }[] = [{ label: '全部', value: 'ALL' }, { label: '待付款', value: 'PENDING_PAYMENT' }, { label: '待发货', value: 'PENDING_SHIPMENT' }, { label: '待收货', value: 'PENDING_RECEIPT' }, { label: '已完成', value: 'COMPLETED' }, { label: '已取消', value: 'CANCELLED' }]
const status = ref<OrderFilter>('ALL'), page = ref<Page<OrderSummary> | null>(null), pageNo = ref(1), loading = ref(false), busy = ref(false), error = ref(''), actionError = ref(''), notice = ref(''), selectedOrder = ref<OrderDetail | null>(null)
const paymentOpen = ref(false), paymentChannel = ref<'ALIPAY' | 'WECHAT'>('ALIPAY'), paymentResult = ref<'SUCCESS' | 'FAILED' | 'CANCELLED'>('SUCCESS')
const afterSaleOpen = ref(false), afterSaleReason = ref(''), afterSaleDescription = ref(''), afterSaleQuantities = ref<Record<number, number>>({})
const reviewTarget = ref<number | null>(null), rating = ref(5), reviewContent = ref('')
const afterSales = ref<Page<AfterSale> | null>(null), afterSalesLoading = ref(false), afterSalesError = ref(''), returnTarget = ref<number | null>(null), returnCarrier = ref(''), returnTracking = ref('')
const labels: Record<string, string> = { PENDING_PAYMENT: '待付款', PENDING_SHIPMENT: '待发货', PENDING_RECEIPT: '待收货', COMPLETED: '已完成', CANCELLED: '已取消' }
function statusText(value: string) { return labels[value] ?? value }
function afterSaleStatus(value: string) { return ({ PENDING_REVIEW: '待审核', WAITING_RETURN: '等待寄回', WAITING_RECEIPT: '等待收货', COMPLETED: '已完成', REJECTED: '已拒绝' } as Record<string, string>)[value] ?? value }
function date(value: string) { return value?.replace('T', ' ').slice(0, 16) }
async function load() { loading.value = true; error.value = ''; try { page.value = await listOrders(status.value, pageNo.value); await loadAfterSales(); if (route.query.orderId) await openOrder(Number(route.query.orderId)) } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } }
async function loadAfterSales() { afterSalesLoading.value = true; afterSalesError.value = ''; try { afterSales.value = await listBuyerAfterSales() } catch (e) { afterSalesError.value = errorMessage(e) } finally { afterSalesLoading.value = false } }
async function openOrder(id: number) { actionError.value = ''; notice.value = ''; try { selectedOrder.value = await getOrder(id); await router.replace({ query: { ...route.query, orderId: String(id) } }) } catch (e) { actionError.value = errorMessage(e) } }
function selectStatus(value: OrderFilter) { status.value = value; pageNo.value = 1; void load() }
function changePage(value: number) { pageNo.value = value; void load() }
async function mutate(action: () => Promise<OrderDetail>, success: string) { if (!selectedOrder.value || busy.value) return; busy.value = true; actionError.value = ''; try { selectedOrder.value = await action(); notice.value = success; await load() } catch (e) { actionError.value = errorMessage(e) } finally { busy.value = false } }
function pay() { if (!selectedOrder.value) return; void mutate(() => payOrder(selectedOrder.value!.id, paymentChannel.value, paymentResult.value), paymentResult.value === 'SUCCESS' ? '支付成功' : paymentResult.value === 'FAILED' ? '模拟支付失败，订单仍待付款' : '已取消支付'); paymentOpen.value = false }
function cancel() { if (selectedOrder.value && window.confirm('确定取消这笔待付款订单吗？')) void mutate(() => cancelOrder(selectedOrder.value!.id), '订单已取消') }
function confirm() { if (selectedOrder.value && window.confirm('确认已收到全部商品？')) void mutate(() => confirmReceipt(selectedOrder.value!.id), '已确认收货') }
function openAfterSale() { afterSaleReason.value = ''; afterSaleDescription.value = ''; afterSaleQuantities.value = Object.fromEntries((selectedOrder.value?.items ?? []).map(i => [i.id, 0])); afterSaleOpen.value = true }
async function submitAfterSaleForm() { if (!selectedOrder.value) return; const items = Object.entries(afterSaleQuantities.value).filter(([, quantity]) => quantity > 0).map(([orderItemId, quantity]) => ({ orderItemId: Number(orderItemId), quantity })); if (!items.length) { actionError.value = '请至少选择一个商品数量'; return } busy.value = true; actionError.value = ''; try { await submitAfterSale(selectedOrder.value.id, { type: selectedOrder.value.status === 'PENDING_SHIPMENT' ? 'REFUND' : 'RETURN', reason: afterSaleReason.value, description: afterSaleDescription.value, items }); afterSaleOpen.value = false; notice.value = '售后申请已提交'; await load() } catch (e) { actionError.value = errorMessage(e) } finally { busy.value = false } }
async function sendReview() { if (!reviewTarget.value) return; busy.value = true; actionError.value = ''; try { await submitReview(reviewTarget.value, rating.value, reviewContent.value); reviewTarget.value = null; reviewContent.value = ''; notice.value = '评价已提交，提交后不可修改'; if (selectedOrder.value) selectedOrder.value = await getOrder(selectedOrder.value.id) } catch (e) { actionError.value = errorMessage(e) } finally { busy.value = false } }
async function sendReturnShipment(id: number) { busy.value = true; afterSalesError.value = ''; try { await returnShipment(id, returnCarrier.value, returnTracking.value); returnTarget.value = null; returnCarrier.value = ''; returnTracking.value = ''; await loadAfterSales() } catch (e) { afterSalesError.value = errorMessage(e) } finally { busy.value = false } }
onMounted(load)
watch(() => route.query.orderId, async (value) => { if (value && Number(value) && !selectedOrder.value) await openOrder(Number(value)) })
</script>
